/**
 * Generated by: adlc-framework/.claude/plugins/commerce/scripts/autotest.sh
 * Flow: order-edit
 * Scope: commerce-autonomous-test-authoring
 *
 * DETERMINISTIC SPEC — no LLM/MCP/agent imports. Plain Playwright.
 *
 * Flow: buyer logs in → navigate to order history page
 *       OE-01: HARD assert URL contains /account/orders
 *       OE-02: HARD assert orders-page-wrapper testid is visible (real DOM assertion)
 *       OE-03: HARD assert "Orders" heading is visible (rendered by page.tsx Heading)
 *       OE-04: CONTENT CHECK — if order rows exist, extract display_id (Approach B)
 *       OE-05: CONTENT CHECK — if order row clickable, navigate to order details
 *       OE-06: CONTENT CHECK — if details page loads, assert back-to-overview button
 *
 * Anti-theater gates:
 *   G1: No soft-pass fallbacks (error-swallowing catch patterns BANNED for hard asserts)
 *   G2: Hard assertions only for URL + testid + heading (steps OE-01..OE-03)
 *   G5: grep -E "mcp|anthropic|agent|claude" order-edit.spec.ts → must return 0 lines
 *
 * Data-testids grounded in source code:
 *   data-testid="orders-page-wrapper" — apps/storefront/.../account/@dashboard/orders/page.tsx:39
 *   data-testid="back-to-overview-button" — apps/storefront/.../order/templates/order-details-template.tsx:29
 *   data-testid="product-name" — apps/storefront/.../order/components/item/index.tsx:16
 *   data-testid="product-quantity" — apps/storefront/.../order/components/item/index.tsx:27
 *
 * Note: networkidle is avoided (unreliable for Next.js RSC streaming).
 * Use domcontentloaded + explicit locator.waitFor() instead.
 */

import path from "node:path";
import { test, expect } from "../fixtures/auth";
import {
  STOREFRONT_URL,
  SCREENSHOTS_DIR,
  TEST_REGION_COUNTRY,
} from "../config";

test.describe("B2B order-edit flow [generated]", () => {
  test("buyer views order history page (OE-01..OE-06)", async ({
    buyerPage,
  }) => {
    // SETUP: Log buyer session state before test starts
    console.log(`[order-edit] SETUP: Starting order-edit test flow. Storefront URL = "${STOREFRONT_URL}"`);

    // OE-01: navigate to /account/orders (order history)
    await buyerPage.goto(`${STOREFRONT_URL}/${TEST_REGION_COUNTRY}/account/orders`);
    await buyerPage.waitForLoadState("domcontentloaded");

    // OE-01: Verify navigation didn't redirect to login (silent auth failure)
    const urlAfterNav = buyerPage.url();
    console.log(`[order-edit] OE-01 NAV: Navigated to URL = "${urlAfterNav}"`);

    // Check for login form as a sign of auth failure
    const loginFormCount = await buyerPage.locator('input[type="email"], input[name="email"]').count();
    if (loginFormCount > 0 && urlAfterNav.includes("/login")) {
      throw new Error(`[order-edit] OE-01 FAIL: Navigation redirected to login page. Auth session may be invalid.`);
    }

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-order-edit-01-orders-page.png"),
    });

    // OE-01: HARD assertion — URL confirms correct navigation
    const currentUrl = buyerPage.url();
    expect(currentUrl).toContain('/account/orders');
    console.log(`[order-edit] OE-01 HARD ASSERT PASS: At orders URL = "${currentUrl}"`);

    // OE-02: HARD assertion — orders-page-wrapper testid is present
    // Grounded in: apps/storefront/src/app/.../account/@dashboard/orders/page.tsx:39
    // data-testid="orders-page-wrapper" is set on the outermost div of the Orders page.

    // Defensive check: confirm URL is still /account/orders (not redirected to login)
    const currentUrlBeforeWrapper = buyerPage.url();
    if (currentUrlBeforeWrapper.includes("/login") || !currentUrlBeforeWrapper.includes("/account/orders")) {
      console.error(`[order-edit] OE-02 PRE-CHECK FAIL: URL changed to "${currentUrlBeforeWrapper}" — buyer session may be invalid or expired`);
      throw new Error(`[order-edit] OE-02: Expected URL to contain /account/orders, but got "${currentUrlBeforeWrapper}"`);
    }

    const ordersWrapper = buyerPage.locator('[data-testid="orders-page-wrapper"]');

    // Count locator instances to diagnose visibility issue
    const wrapperCount = await ordersWrapper.count();
    if (wrapperCount === 0) {
      // Wrapper div not in DOM — likely RSC streaming hasn't rendered the page yet
      console.error("[order-edit] OE-02 FAIL: orders-page-wrapper not found in DOM");

      // Log page HTML (first 1000 chars) for debugging
      const pageContent = await buyerPage.content();
      const htmlSnippet = pageContent.substring(0, 1000);
      console.error("[order-edit] OE-02 DEBUG: Page HTML (first 1000 chars):\n", htmlSnippet);

      // Check if login form is present (sign of auth failure)
      const hasLoginForm = await buyerPage.locator('input[type="email"], input[name="email"]').count();
      if (hasLoginForm > 0) {
        throw new Error("[order-edit] OE-02: Login form detected on /account/orders — buyer session invalid or auth failed");
      }

      throw new Error("[order-edit] OE-02: orders-page-wrapper div not rendered in DOM after domcontentloaded");
    }

    console.log(`[order-edit] OE-02 DOM CHECK: orders-page-wrapper found (count=${wrapperCount})`);

    // Wait for the wrapper to be visible (may be off-screen or hidden by CSS)
    await ordersWrapper.first().waitFor({ state: "visible", timeout: 10000 }).catch(async (err) => {
      console.error("[order-edit] OE-02 FAIL: wrapper found in DOM but not visible after 10s");
      const isHidden = await ordersWrapper.first().isHidden().catch(() => false);
      if (isHidden) {
        console.error("[order-edit] OE-02 DEBUG: wrapper is explicitly hidden (display:none or visibility:hidden)");
      }
      throw err;
    });

    console.log("[order-edit] OE-02 HARD ASSERT PASS: orders-page-wrapper testid visible");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-order-edit-02-orders-wrapper.png"),
    });
    // Flow capture: step-01-orders-wrapper (logged-in buyer view)
    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "../demo/flows/08-order-edit/step-01-orders-wrapper.png"),
    }).catch(() => {
      // Dir may not exist yet; batch gate creates it
    });

    // OE-03: HARD assertion — "Orders" heading is visible
    // Grounded in: page.tsx Heading component renders "Orders" as h1-level text

    // Strategy: Try multiple selector approaches (order page may use h1, h2, or role="heading")
    const ordersHeading = buyerPage.locator('h1:has-text("Orders"), h2:has-text("Orders")')
      .or(buyerPage.getByRole("heading", { name: "Orders" }))
      .or(buyerPage.locator('h1').filter({ hasText: "Orders" }))
      .or(buyerPage.locator('h2').filter({ hasText: "Orders" }));

    const headingCount = await ordersHeading.count();
    if (headingCount === 0) {
      console.error("[order-edit] OE-03 FAIL: 'Orders' heading not found in DOM");
      const bodyText = await buyerPage.textContent("body");
      console.error("[order-edit] OE-03 DEBUG: Page body text (first 500 chars):\n", bodyText?.substring(0, 500));
      throw new Error("[order-edit] OE-03: 'Orders' heading not found in DOM");
    }

    console.log(`[order-edit] OE-03 DOM CHECK: 'Orders' heading found (count=${headingCount})`);

    await expect(ordersHeading.first()).toBeVisible({ timeout: 10000 });
    console.log("[order-edit] OE-03 HARD ASSERT PASS: 'Orders' heading visible");

    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "generated-order-edit-03-orders-heading.png"),
    });
    // Flow capture: step-02-orders-heading (logged-in buyer view)
    await buyerPage.screenshot({
      path: path.join(SCREENSHOTS_DIR, "../demo/flows/08-order-edit/step-02-orders-heading.png"),
    }).catch(() => {
      // Dir may not exist yet; batch gate creates it
    });

    // OE-04: CONTENT CHECK (Approach B) — if order rows exist, extract display_id
    // The buyer fixture uses demo-buyer@democorp.local — may have 0 orders in a fresh seed.
    // Runtime-extract: not a hard assertion (empty state is valid).
    const firstOrderRow = ordersWrapper.locator('a[href*="/orders/details"]').first()
      .or(ordersWrapper.locator('[data-testid="order-row"]').first())
      .or(ordersWrapper.locator('table tbody tr').first());

    const isOrderVisible = await firstOrderRow.isVisible({ timeout: 3000 }).catch(() => false);

    if (isOrderVisible) {
      // Extract display_id/order number text from row
      const orderIdText = await firstOrderRow.textContent({ timeout: 2000 }).catch(() => "");
      console.log(`[order-edit] OE-04 CONTENT CHECK (runtime-extracted): Order row text = "${orderIdText?.trim().substring(0, 80)}"`);

      // OE-05: CONTENT CHECK — navigate to order details page
      await firstOrderRow.click();
      await buyerPage.waitForLoadState("domcontentloaded");
      await buyerPage.waitForTimeout(1000);

      await buyerPage.screenshot({
        path: path.join(SCREENSHOTS_DIR, "generated-order-edit-04-order-details.png"),
      });

      const detailsUrl = buyerPage.url();
      console.log(`[order-edit] OE-05 CONTENT CHECK: Navigated to "${detailsUrl}"`);

      if (detailsUrl.includes("/orders/details/")) {
        // OE-06: CONTENT CHECK — back-to-overview button exists on details page
        // Grounded in: order-details-template.tsx:29 data-testid="back-to-overview-button"
        const backBtn = buyerPage.locator('[data-testid="back-to-overview-button"]');
        const isBackVisible = await backBtn.isVisible({ timeout: 5000 }).catch(() => false);
        if (isBackVisible) {
          console.log("[order-edit] OE-06 CONTENT CHECK PASS: back-to-overview-button visible on details page");
        } else {
          console.log("[order-edit] OE-06 CONTENT CHECK: back-to-overview-button not visible (details page may differ)");
        }
      }
    } else {
      // Empty order history is valid for a demo buyer that has not placed orders.
      console.log("[order-edit] OE-04 CONTENT CHECK: No order rows visible (empty history — expected for fresh buyer)");
      await buyerPage.screenshot({
        path: path.join(SCREENSHOTS_DIR, "generated-order-edit-04-empty-orders.png"),
      });
    }

    console.log("[order-edit] Flow complete — OE-01..OE-03 hard asserts passed");
  });
});
